const settleAsyncJobsReactedFailed = `-- name: SettleAsyncJobsReactedFailed :execrows
UPDATE async_jobs SET reacted = 1, reacted_failed = 1, updated_at = ?
WHERE owner_session_id = ? AND tool_call_id IN (/*SLICE:tool_call_ids*/?) AND wake = 1 AND reacted = 0
`

type SettleAsyncJobsReactedFailedParams struct {
	UpdatedAt      int64    `json:"updated_at"`
	OwnerSessionID string   `json:"owner_session_id"`
	ToolCallIds    []string `json:"tool_call_ids"`
}

// Settle-by-failure step 2, after K=3 (doc sec.3.4): closes debt on exactly
// the id set captured at the start of the failed turn -- doc: "only for the
// rows that were done at the moment it started" -- not every currently-pending
// row of the owner (a notice that arrived mid-retry must get its own future
// wake-up call, not be silently absorbed into this closure). reacted_failed
// distinguishes this from an ordinary step-persisted reaction
// (MarkAsyncJobsReactedForOwner): it is set ONLY here, never by a real
// step, so a child session can tell its parent the delegation failed
// instead of succeeded-with-no-output.
func (q *Queries) SettleAsyncJobsReactedFailed(ctx context.Context, arg SettleAsyncJobsReactedFailedParams) (int64, error) {
	query := settleAsyncJobsReactedFailed
	var queryParams []interface{}
	queryParams = append(queryParams, arg.UpdatedAt)
	queryParams = append(queryParams, arg.OwnerSessionID)
	if len(arg.ToolCallIds) > 0 {
		for _, v := range arg.ToolCallIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:tool_call_ids*/?", strings.Repeat(",?", len(arg.ToolCallIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:tool_call_ids*/?", "NULL", 1)
	}
	result, err := q.exec(ctx, nil, query, queryParams...)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const transitionAsyncJobTerminalPreserveVoid = `-- name: TransitionAsyncJobTerminalPreserveVoid :one
UPDATE async_jobs
SET state = ?, notice_kind = ?, result_summary = ?, result_is_error = ?,
    delivery = CASE delivery WHEN 'void' THEN 'void' ELSE ? END,
    wake = ?, updated_at = ?
WHERE owner_session_id = ? AND tool_call_id = ? AND state = 'running'
RETURNING owner_session_id, tool_call_id, kind, tool_name, timeout_seconds, input_hash, child_session_id, origin_cli, state, notice_kind, host_id, announced, delivery, notice_message_id, wake, reacted, wake_attempts, reacted_failed, deadline_at, timeout_kind, result_summary, result_is_error, created_at, updated_at
`

type TransitionAsyncJobTerminalPreserveVoidParams struct {
	State          string         `json:"state"`
	NoticeKind     string         `json:"notice_kind"`
	ResultSummary  sql.NullString `json:"result_summary"`
	ResultIsError  sql.NullInt64  `json:"result_is_error"`
	Delivery       string         `json:"delivery"`
	Wake           int64          `json:"wake"`
	UpdatedAt      int64          `json:"updated_at"`
	OwnerSessionID string         `json:"owner_session_id"`
	ToolCallID     string         `json:"tool_call_id"`
}

// The ONE terminal-transition CAS (DUR-1/DUR-2/step-2 review): a terminal
// state, its cause (notice_kind), the result payload, delivery, and wake
// are all set by this single statement, scoped to state='running' so only
// the first committer wins -- every other concurrent caller sees 0 rows
// affected and must re-read the row (GetAsyncJob) and accept whatever
// state is there instead of retrying the same transition. This is the
// ONLY terminal-transition query (doc sec.3.8 is explicit the terminal
// transition always preserves void, so the earlier non-preserving sibling
// this replaced -- TransitionAsyncJobTerminal -- is gone, not a second,
// parallel path): a row already voided by Rerun truncation must not be
// resurrected to 'pending' by a late-arriving terminal transition (e.g.
// job_kill racing the history truncation).
//
// delivery is a PARAMETER, not a hardcoded 'pending' literal (step 3): every
// cause passes 'pending' today; step 6 passes 'done' for job_kill once its
// own tool response carries the real output (doc sec.3.2), so that row never
// also surfaces as a history notice via the pull.
func (q *Queries) TransitionAsyncJobTerminalPreserveVoid(ctx context.Context, arg TransitionAsyncJobTerminalPreserveVoidParams) (AsyncJob, error) {
	row := q.queryRow(ctx, q.transitionAsyncJobTerminalPreserveVoidStmt, transitionAsyncJobTerminalPreserveVoid,
		arg.State,
		arg.NoticeKind,
		arg.ResultSummary,
		arg.ResultIsError,
		arg.Delivery,
		arg.Wake,
		arg.UpdatedAt,
		arg.OwnerSessionID,
		arg.ToolCallID,
	)
	var i AsyncJob
	err := row.Scan(
		&i.OwnerSessionID,
		&i.ToolCallID,
		&i.Kind,
		&i.ToolName,
		&i.TimeoutSeconds,
		&i.InputHash,
		&i.ChildSessionID,
		&i.OriginCli,
		&i.State,
		&i.NoticeKind,
		&i.HostID,
		&i.Announced,
		&i.Delivery,
		&i.NoticeMessageID,
		&i.Wake,
		&i.Reacted,
		&i.WakeAttempts,
		&i.ReactedFailed,
		&i.DeadlineAt,
		&i.TimeoutKind,
		&i.ResultSummary,
		&i.ResultIsError,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

